<!--
 * Agent 审批处理（弹窗组件）
 *
 * @path apps/agent-web/src/views/approval/approval-form.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * Agent 审批处理（弹窗组件）
 * <p>消费后端 HumanApprovalController 契约（auto-generated by bash/gen-contract.py）：
 * 打开时按 record.id 通过 getApproval({ id }) 加载详情展示，附审批意见输入框；
 * 「通过」调用 approve({ id }, { comment })，「驳回」调用 reject({ id }, { comment })，成功后 emit('success')。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import { ElButton, ElDescriptions, ElDescriptionsItem, ElForm, ElFormItem, ElInput, ElMessage } from 'element-plus';
import { computed, ref } from 'vue';
import { approve, getApproval, reject } from '#/api/humanApproval';

/** 审批处理成功后触发，通知父级刷新列表 */
const emit = defineEmits<{ success: [] }>();
/** 当前审批单 ID（由父级 setData({ record }) 传入） */
const approvalId = ref('');
/** 审批意见 */
const comment = ref('');
/** 审批详情（getApproval 返回结构不确定，逐字段兼容展示） */
const detail = ref<Record<string, unknown>>({});
const detailLoading = ref(false);
/** 提交中标记 */
const submitting = ref(false);

/** 审批详情条目（v-for 渲染用） */
const detailEntries = computed<[string, unknown][]>(() => Object.entries(detail.value));

/**
 * 将未知取值安全转为展示字符串，空值统一显示为 '-'，对象转为 JSON。
 *
 * @param value - 待展示的未知取值
 * @returns 展示字符串
 */
function displayValue(value: unknown): string {
  if (value === null || value === undefined) { return '-'; }
  if (typeof value === 'object') {
    try { return JSON.stringify(value); } catch { return String(value); }
  }
  return String(value);
}

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: async (isOpen) => {
    if (!isOpen) { return; }
    comment.value = '';
    detail.value = {};
    const data = modalApi.getData<{ record?: { id?: string } }>();
    approvalId.value = data?.record?.id ?? '';
    if (!approvalId.value) { return; }
    detailLoading.value = true;
    try {
      const res = await getApproval({ id: approvalId.value });
      detail.value = res && typeof res === 'object' ? (res as Record<string, unknown>) : {};
    } catch {
      detail.value = {};
    } finally {
      detailLoading.value = false;
    }
  },
});

/** 提交审批处理：action 为 approve / reject */
async function handleSubmit(action: 'approve' | 'reject') {
  if (!approvalId.value) { return; }
  submitting.value = true;
  modalApi.lock();
  try {
    const params = { comment: comment.value.trim() || undefined };
    if (action === 'approve') {
      await approve({ id: approvalId.value }, params);
      ElMessage.success('已通过');
    } else {
      await reject({ id: approvalId.value }, params);
      ElMessage.success('已驳回');
    }
    emit('success');
    modalApi.close();
  } finally {
    modalApi.unlock();
    submitting.value = false;
  }
}
</script>
<template>
  <Modal title="审批处理">
    <div v-if="detailLoading" class="py-8 text-center text-sm text-gray-400">详情加载中...</div>
    <ElDescriptions v-else-if="detailEntries.length" :column="1" border class="mb-4">
      <ElDescriptionsItem v-for="[key, value] in detailEntries" :key="key" :label="key">
        <pre class="whitespace-pre-wrap break-all text-sm">{{ displayValue(value) }}</pre>
      </ElDescriptionsItem>
    </ElDescriptions>
    <ElForm label-width="100px" label-position="right">
      <ElFormItem label="审批意见">
        <ElInput v-model="comment" type="textarea" :rows="3" placeholder="请输入审批意见（可选）" />
      </ElFormItem>
    </ElForm>
    <div class="mt-2 flex justify-end gap-2">
      <ElButton type="danger" :loading="submitting" @click="handleSubmit('reject')">驳回</ElButton>
      <ElButton type="success" :loading="submitting" @click="handleSubmit('approve')">通过</ElButton>
    </div>
  </Modal>
</template>